        state: { type: string, enum: [running, paused, unknown, stopped] }
        occurredAt: { $ref: '#/components/schemas/Rfc3339Utc' }
        verificationRevision: { allOf: [{ $ref: '#/components/schemas/BigintString' }], nullable: true }
        continuityValid: { type: boolean, nullable: true, description: 客户端使用者连续性是否仍成立 }
    ExecutionRecord:
      type: object
      description: >-
