        executionStatus: { type: string, enum: [admitted, running, paused, unknown, stopped, closed] }
        acceptedCount: { $ref: '#/components/schemas/BigintString' }
        progress: { allOf: [{ $ref: '#/components/schemas/Progress' }], nullable: true, description: 仅具备读取权限时附带 }
    ExecutionClosureRequest:
