      additionalProperties: false
      properties:
        stopObservationSeq: { $ref: '#/components/schemas/BigintString' }
        reason: { type: string, description: "结束原因（枚举未冻结，如 user_finished；x-detail: skeleton）" }
        recordStreamEpoch: { type: string, minLength: 1, maxLength: 128 }
        finalRecordSeq: { $ref: '#/components/schemas/BigintString' }
        finalCount: { $ref: '#/components/schemas/BigintString' }
    MissingRange:
      type: object
      required: [from, to]
      additionalProperties: false
      description: 记录缺口范围（有上限输出；不生成与巨大 W 成比例的数组）
